"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["16"],{9664(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>h,frontMatter:()=>r,contentTitle:()=>o,toc:()=>l,assets:()=>c});var i=JSON.parse('{"id":"networks/vlans","title":"vlans","description":".md---","source":"@site/docs/networks/13-vlans.md","sourceDirName":"networks","slug":"/networks/vlans","permalink":"/Mindstack/docs/networks/vlans","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":13,"frontMatter":{},"sidebar":"networkSidebar","previous":{"title":"Switching Fundamentals","permalink":"/Mindstack/docs/networks/switching-fundamentals"},"next":{"title":"Spanning Tree (STP)","permalink":"/Mindstack/docs/networks/stp"}}'),a=t(4848),s=t(8453);let r={},o,c={},l=[{value:".md---\ntitle: &quot;VLANs&quot;\nsidebar_label: &quot;VLANs&quot;\nsidebar_position: 13",id:"md---title-vlanssidebar_label-vlanssidebar_position-13",level:2},{value:"Why VLANs Exist",id:"why-vlans-exist",level:2},{value:"VLAN Tagging \u2014 IEEE 802.1Q",id:"vlan-tagging--ieee-8021q",level:2},{value:"Access Ports vs Trunk Ports",id:"access-ports-vs-trunk-ports",level:2},{value:"Native VLAN",id:"native-vlan",level:2},{value:"VLAN Configuration (Cisco IOS)",id:"vlan-configuration-cisco-ios",level:2},{value:"Voice VLAN",id:"voice-vlan",level:2},{value:"VLAN Trunking Protocol (VTP) \u2014 Historical Context",id:"vlan-trunking-protocol-vtp--historical-context",level:2},{value:"Private VLANs (PVLANs) \u2014 Advanced Isolation",id:"private-vlans-pvlans--advanced-isolation",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.h2,{id:"md---title-vlanssidebar_label-vlanssidebar_position-13",children:'.md---\ntitle: "VLANs"\nsidebar_label: "VLANs"\nsidebar_position: 13'}),"\n",(0,a.jsx)(n.h1,{id:"vlans",children:"VLANs"}),"\n",(0,a.jsx)(n.p,{children:"A Virtual LAN (VLAN) divides a single physical switch (or set of switches) into multiple logically separate broadcast domains, without requiring separate physical hardware for each. VLANs are one of the most consequential and widely-used Layer 2 technologies in all of enterprise networking."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"why-vlans-exist",children:"Why VLANs Exist"}),"\n",(0,a.jsx)(n.p,{children:"Before VLANs (1990s and earlier), achieving network segmentation required physically separate switches for each group of devices that needed isolation \u2014 expensive, inflexible, and wasteful when groups didn't need a full switch's worth of ports."}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"Without VLANs:                    With VLANs:\n[Switch A]\u2500\u2500Finance PCs           [One Switch]\u2500\u2500Finance PCs (VLAN 10)\n[Switch B]\u2500\u2500Engineering PCs                  \u2514\u2500\u2500Engineering PCs (VLAN 20)\n[Switch C]\u2500\u2500Guest PCs                        \u2514\u2500\u2500Guest PCs (VLAN 30)\n\nSame physical switch, same cabling \u2014 but Finance, Engineering, and\nGuest are now in completely separate broadcast domains, as if they\nwere on entirely separate physical switches.\n"})}),"\n",(0,a.jsx)(n.p,{children:"VLANs solve several problems simultaneously:"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"Broadcast control \u2014 limits broadcast domain size (see Switching\n  Fundamentals), improving performance as networks grow\nSecurity/Isolation \u2014 devices in different VLANs cannot communicate\n  without going through a Layer 3 device (router or L3 switch) with\n  explicit routing/policy configured \u2014 accidental cross-department\n  visibility is eliminated by design\nFlexibility \u2014 devices can be grouped logically (by department, function,\n  or security level) independent of their PHYSICAL location/cabling \u2014\n  a Finance PC on the 3rd floor and one on the 1st floor can be in the\n  same VLAN despite being on different physical switches\nSimplified moves/adds/changes \u2014 moving a user to a different VLAN is\n  a switchport configuration change, not a re-cabling project\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"vlan-tagging--ieee-8021q",children:"VLAN Tagging \u2014 IEEE 802.1Q"}),"\n",(0,a.jsx)(n.p,{children:'For a single physical link to carry traffic from MULTIPLE VLANs (a "trunk" link, typically between switches or a switch and a router), frames must be tagged to indicate which VLAN they belong to.'}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'Standard Ethernet Frame:\n\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 Dest MAC \u2502 Src MAC  \u2502 Type \u2502 Payload \u2502 FCS \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2518\n\n802.1Q Tagged Frame (4 extra bytes inserted after the Source MAC):\n\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 Dest MAC \u2502 Src MAC  \u2502 802.1Q Tag   \u2502 Type \u2502 Payload \u2502 FCS \u2502\n\u2502          \u2502          \u2502 (4 bytes)    \u2502      \u2502         \u2502     \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2518\n\nThe 802.1Q tag itself breaks down as:\n\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 TPID (0x8100)  \u2502 PCP \u2502 DEI \u2502 VLAN ID (12b) \u2502\n\u2502 16 bits        \u2502 3b  \u2502 1b  \u2502               \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nTPID (Tag Protocol Identifier) \u2014 fixed value 0x8100, signals "this is\n  an 802.1Q tagged frame" (this is the EtherType seen in Ethernet\n  Fundamentals\' EtherType reference table)\nPCP (Priority Code Point) \u2014 3 bits, used for QoS marking/prioritization\n  (see QoS)\nDEI (Drop Eligible Indicator) \u2014 1 bit, marks frames as eligible to be\n  dropped first under congestion\nVLAN ID \u2014 12 bits, giving a theoretical range of 0-4095 VLANs\n  (0 and 4095 are reserved, and VLAN 1 is typically a default/management\n  VLAN by convention \u2014 practical usable range is 1-4094, with 1002-1005\n  historically reserved on Cisco equipment for legacy Token Ring/FDDI)\n'})}),"\n",(0,a.jsx)(n.p,{children:"Because the tag adds 4 bytes, a maximum-size tagged Ethernet frame is 1522 bytes instead of the standard 1518 \u2014 a detail that occasionally matters for devices with strict frame size limits."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"access-ports-vs-trunk-ports",children:"Access Ports vs Trunk Ports"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"Access Port \u2014 carries traffic for exactly ONE VLAN, untagged. This is\n  how an end device (PC, printer, phone) connects \u2014 the device itself\n  has no awareness of VLANs at all; the switch silently associates\n  that port (and therefore the device) with a specific VLAN.\n\nTrunk Port \u2014 carries traffic for MULTIPLE VLANs simultaneously, using\n  802.1Q tags to distinguish which frame belongs to which VLAN. Used\n  between switches, and between a switch and a router (or firewall)\n  performing inter-VLAN routing.\n"})}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"                    Trunk (VLANs 10,20,30 tagged)\n[Switch A]\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550[Switch B]\n   \u2502                                              \u2502\n   \u2502 Access (VLAN 10)                             \u2502 Access (VLAN 20)\n  [PC-1]                                         [PC-2]\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"native-vlan",children:"Native VLAN"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'On a trunk port, ONE VLAN can be designated the "native VLAN" \u2014 frames\nbelonging to the native VLAN are sent UNTAGGED across the trunk\n(a legacy compatibility feature for devices/links that don\'t support\n802.1Q tagging at all).\n\nCritical security/operational note: if the native VLAN doesn\'t MATCH\non both ends of a trunk, frames can be misdelivered to the wrong VLAN\n(a "VLAN hopping" attack vector \u2014 see Network Attacks & Defense) \u2014\nbest practice is to EXPLICITLY set the native VLAN to match on both\nends, and many security guidelines recommend using an unused, non-default\nVLAN as the native VLAN (rather than the default VLAN 1) specifically\nto reduce attack surface.\n'})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"vlan-configuration-cisco-ios",children:"VLAN Configuration (Cisco IOS)"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"! Creating VLANs\nSwitch(config)# vlan 10\nSwitch(config-vlan)# name Finance\nSwitch(config-vlan)# exit\nSwitch(config)# vlan 20\nSwitch(config-vlan)# name Engineering\nSwitch(config-vlan)# exit\n\n! Configuring an access port\nSwitch(config)# interface gigabitethernet 0/1\nSwitch(config-if)# switchport mode access\nSwitch(config-if)# switchport access vlan 10\n\n! Configuring a trunk port\nSwitch(config)# interface gigabitethernet 0/24\nSwitch(config-if)# switchport mode trunk\nSwitch(config-if)# switchport trunk allowed vlan 10,20,30\nSwitch(config-if)# switchport trunk native vlan 99\n\n! Verification\nSwitch# show vlan brief\nSwitch# show interfaces trunk\nSwitch# show interfaces gi0/1 switchport\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"voice-vlan",children:"Voice VLAN"}),"\n",(0,a.jsx)(n.p,{children:"A specific, very common real-world VLAN pattern: IP phones with a built-in switch passthrough port for a connected PC."}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"                [Switch Port]\n                      \u2502\n                  [IP Phone] \u2500\u2500 (Voice VLAN, tagged)\n                      \u2502\n                    [PC]   \u2500\u2500 (Data/Access VLAN, untagged)\n\nThe switch port is configured as an access port for the DATA VLAN\n(for the PC) AND a separate voice VLAN (for the phone itself, tagged) \u2014\nboth riding the same physical cable to the desk, with the phone\nintelligently tagging its own traffic while passing the PC's untagged\ntraffic straight through unchanged.\n\n! Configuration\nSwitch(config)# interface gigabitethernet 0/5\nSwitch(config-if)# switchport mode access\nSwitch(config-if)# switchport access vlan 10\nSwitch(config-if)# switchport voice vlan 110\n"})}),"\n",(0,a.jsx)(n.p,{children:"This pattern lets organizations run separate QoS policy, security policy, and broadcast domains for voice traffic vs general data traffic, over a single cable run to each desk \u2014 eliminating the need for two separate cable drops."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"vlan-trunking-protocol-vtp--historical-context",children:"VLAN Trunking Protocol (VTP) \u2014 Historical Context"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'VTP (Cisco proprietary) was designed to let one switch propagate VLAN\ndatabase changes automatically to other switches in a "VTP domain,"\navoiding the need to manually create matching VLANs on every switch.\n\nModes:\n  Server  \u2014 can create/modify/delete VLANs, propagates changes\n  Client  \u2014 receives and applies changes from a server, cannot make\n            its own changes\n  Transparent \u2014 passes VTP messages through but maintains its own\n            independent, locally-configured VLAN database\n\nVTP is widely considered a legacy/risky feature today: a classic,\nwell-known operational disaster scenario involves a NEW switch with a\nHIGHER VTP revision number than the existing domain accidentally\nwiping out the entire production VLAN database when connected \u2014 for\nthis reason, many organizations explicitly avoid VTP server/client\nmodes in production and use VTP transparent mode (or simply configure\nVLANs manually/via automation on each switch) instead.\n'})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"private-vlans-pvlans--advanced-isolation",children:"Private VLANs (PVLANs) \u2014 Advanced Isolation"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"A further refinement allowing isolation WITHIN a single VLAN:\n\nPrimary VLAN \u2014 the overall VLAN\n  Community VLAN \u2014 ports can talk to each other AND to promiscuous ports,\n                   but not to isolated ports or other community VLANs\n  Isolated VLAN  \u2014 ports can ONLY talk to promiscuous ports, never to\n                   each other or to community VLAN ports\n  Promiscuous port \u2014 typically the router/gateway port, can talk to everyone\n\nCommon use case: hotel/guest Wi-Fi or shared hosting environments where\neach device should reach the internet gateway but NEVER see or\ncommunicate with other devices on the same subnet.\n"})}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Always explicitly configure the native VLAN to match on both ends of every trunk \u2014 relying on the default (VLAN 1) is a known security risk and a common source of subtle misconfiguration."}),"\n",(0,a.jsxs)(n.li,{children:["When troubleshooting \"two devices in the same VLAN can't communicate but everything else works,\" check the trunk's allowed VLAN list (",(0,a.jsx)(n.code,{children:"switchport trunk allowed vlan"}),") \u2014 a VLAN accidentally excluded from a trunk's allowed list is a very common real-world mistake."]}),"\n",(0,a.jsx)(n.li,{children:"VTP's automatic propagation has caused enough real production outages industry-wide that defaulting to VTP transparent mode (or avoiding VTP server/client entirely) is now widely considered a safer default in modern deployments."}),"\n",(0,a.jsx)(n.li,{children:"Voice VLAN is the standard pattern for any deployment with desk IP phones \u2014 it lets one cable serve both the phone and the PC behind it with appropriate, separate QoS and broadcast domain treatment."}),"\n"]}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"VLANs create logically separate broadcast domains on shared physical switch hardware, providing segmentation, security isolation, and flexibility without separate physical switches per group."}),"\n",(0,a.jsx)(n.li,{children:"802.1Q tagging adds a 4-byte tag (including a 12-bit VLAN ID, supporting up to 4094 usable VLANs) to frames crossing trunk links."}),"\n",(0,a.jsx)(n.li,{children:"Access ports carry one untagged VLAN for end devices; trunk ports carry multiple tagged VLANs between switches/routers."}),"\n",(0,a.jsx)(n.li,{children:"The native VLAN is sent untagged across a trunk for legacy compatibility \u2014 mismatched native VLANs between trunk ends is a real security risk (VLAN hopping)."}),"\n",(0,a.jsx)(n.li,{children:"Voice VLAN lets a single cable serve both an IP phone and a connected PC with separate VLAN/QoS treatment for each."}),"\n",(0,a.jsx)(n.li,{children:"VTP automates VLAN database propagation but has a well-documented history of causing accidental production outages \u2014 many organizations now avoid it in favor of manual or automated-but-controlled VLAN configuration."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var i=t(6540);let a={},s=i.createContext(a);function r(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);